{"id": "v19/support/substitute", "version": 1, "symbol": "substitute", "kind": "constructor", "status": "Accepted", "signature": "TERM substitute(original: STRING / TERM, replacement: STRING / TERM, purpose?: STRING / TERM) -> TERM", "definition": "Constructs a descriptive representation of substituting an original entity or ingredient with a replacement alternative.", "not": "an executed change or runtime revision (use LINK revises)", "aliases": ["substitute", "substitution", "alternative for", "replace with"], "shared_rules": ["v19/rule/support-primitives-general"]}
